import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import { caret, xCircle } from "../../../icons";
import FormControl from "../../functional-components/form-control/form-control";
import { attachElementInternals } from "../../utils/element-internals";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import { hasSlot } from "../../utils/slot";

let id = 0;

type BaseProps = {
	onClick?: (e: MouseEvent) => void;
};

/**
 * @since 2.4.0
 * @status beta
 *
 * @data-testid clear-button - The default clear button shown when the combobox has a clearable value.
 *
 * @slot label - The input's label. Alternatively, you can use the label prop.
 * @slot label-suffix - Non-interactive content to display inline with the input label.
 * @slot label-info - Interactive informational content, such as a tooltip trigger, displayed next to the input label.
 * @slot prefix - Used to prepend an icon or similar element to the input.
 * @slot suffix - Used to append an icon or similar element to the input.
 * @slot clear-icon - An icon to use in lieu of the default clear icon.
 * @slot help-text - deprecated, do not use this slot, put help text outside the component
 *
 * @part base - The component's base wrapper.
 * @part form-control - The form control that wraps the label, input, and help-text.
 * @part label-container - The container that wraps the label and label-info slot.
 * @part label - The input label.
 * @part input - The input control.
 * @part prefix - The input prefix container.
 * @part clear-button - The clear button.
 * @part suffix - The input suffix container.
 */

@Component({
	tag: "hbr-combobox",
	styleUrl: "combobox.scss",
	shadow: true,
	formAssociated: true,
})
export class Combobox {
	inputId = `combobox-${++id}`;
	labelId = `combobox-label-${id}`;
	suffixId = `combobox-suffix-label--${id}`;
	prefixId = `combobox-prefix-label--${id}`;
	helpTextId = `combobox-help-text-${id}`;
	input: HTMLInputElement;
	unsubscribe;

	@Element() host: HTMLHbrComboboxElement;

	private internals?: ElementInternals;

	@State() hasFocus = false;
	@State() hasHelpTextSlot = false;
	@State() hasLabelSlot = false;
	@State() hasLabelInfoSlot = false;
	@State() hasFrontSlot = false;
	@State() hasRearSlot = false;
	@State() hasPrefixSlot = false;
	@State() hasSuffixSlot = false;
	@State() requiredAfterFocus = false;
	@State() hasElementSuffix = false;

	/**
	 * The type of input. Works the same as a native `<input>` element, but only a subset of types are supported. Defaults
	 * to `text`.
	 */
	@Prop({ reflect: true }) type:
		| "date"
		| "email"
		| "number"
		| "search"
		| "tel"
		| "text"
		| "url" = "text";

	// The input's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	@Prop({ reflect: true }) dynamicInputWidth = false;

	/** The name of the input, submitted as a name/value pair with form data. */
	@Prop({ reflect: true }) name = "";

	/** The value become the placeholder when the input is focused */
	@Prop({ reflect: true }) dynamicPlaceholder = false;

	/** Multiple select. */
	@Prop({ reflect: true }) multiple = false;

	/** Enable the searchable */
	@Prop({ reflect: true }) searchable = false;

	/** Show the expand icon. */
	@Prop({ reflect: true }) expandIcon = true;

	/** The current value of the input. */
	@Prop({ mutable: true, reflect: true }) inputValue = "";

	/** The component value, submitted as a name/value pair with form data. */
	@Prop({ mutable: true, reflect: true }) value: string | Array<string> = "";

	/** The input's label. If you need to display HTML, use the `label` slot instead. */
	@Prop() label = "";

	/** Placeholder text to show as a hint when the input is empty. */
	@Prop() placeholder: string;

	@Prop({ reflect: true }) open = false;

	/** Disables the input. */
	@Prop({ reflect: true }) disabled = false;

	/** Makes the input readonly. */
	@Prop({ reflect: true }) readonly = false;

	/** The minimum length of input that will be considered valid. */
	@Prop({ reflect: true }) minlength: number;

	/** The maximum length of input that will be considered valid. */
	@Prop({ reflect: true }) maxlength: number;

	/** The input's minimum value. Only applies to date and number input types. */
	@Prop({ reflect: true }) min: number;

	/** The input's maximum value. Only applies to date and number input types. */
	@Prop({ reflect: true }) max: number;

	/**
	 * Specifies the granularity that the value must adhere to, or the special value `any` which means no stepping is
	 * implied, allowing any numeric value. Only applies to date and number input types.
	 */
	@Prop({ reflect: true }) step: number | "any";

	/** A regular expression pattern to validate input against. */
	@Prop({ reflect: true }) pattern: string;

	/** Makes the input a required field. */
	@Prop({ reflect: true }) required: boolean;

	/**
	 * This will be true when the control is in an invalid state. Validity is determined by props such as `type`,
	 * `required`, `minlength`, `maxlength`, and `pattern` using the browser's constraint validation API.
	 */
	@Prop({ mutable: true, reflect: true }) invalid = false;

	/** Controls whether and how text input is automatically capitalized as it is entered by the user. */
	@Prop() autocapitalize:
		| "off"
		| "none"
		| "on"
		| "sentences"
		| "words"
		| "characters";

	/** Indicates whether the browser's autocorrect feature is on or off. */
	@Prop() autocorrect: string;

	/**
	 * Specifies what permission the browser has to provide assistance in filling out form field values. Refer to
	 * [this page on MDN](https://developer.mozilla.org/en-US/docs/Web/HTML/Attributes/autocomplete) for available values.
	 */
	@Prop() autocomplete: string;

	/** Indicates that the input should receive focus on page load. */
	@Prop() autofocus: boolean;

	/** Enables spell checking on the input. */
	@Prop() spellcheck: boolean;

	/** Adds a clear button when the input is not empty. */
	@Prop() clearable = true;

	/**
	 * Tells the browser what type of data will be entered by the user, allowing it to display the appropriate virtual
	 * keyboard on supportive devices.
	 */
	@Prop() inputmode:
		| "none"
		| "text"
		| "decimal"
		| "numeric"
		| "tel"
		| "search"
		| "email"
		| "url";

	/** Indicates that the input has an error */
	@Prop() error = false;

	/** Deprecate candidate. Use "aria={label: value}" instead. */
	@Prop() arialabel: string;

	/** Tooltip content if the icon button serves as a tooltip reference. */
	@Prop({ reflect: true }) tooltip: string;

	/** Deprecate candidate. Use "aria={haspopup: value}" instead. */
	@Prop() ariahaspopup = "dialog";

	/** Deprecate candidate. Use "aria={controls: value}" instead. */
	@Prop() ariacontrols = undefined;

	/** Deprecate candidate. Use "aria={role: value}" instead. */
	@Prop() ariarole = "combobox";

	/** Attributes related to screen readers. */
	@Prop() aria: {
		label: string;
		deleteInputContent: string;
		role: string;
		controls: undefined;
		haspopup: string | boolean;
	};

	@Watch("helpText")
	@Watch("label")
	handleLabelChange() {
		this.handleSlotChange();
	}

	@Watch("value")
	handleValueChange() {
		// In rare cases, the watcher may be called before render so we need to make sure the input exists
		this.invalid = this.input ? !this.input.checkValidity() : false;
		const value = this.getValue();
		const formValue = Array.isArray(value) ? value.join(",") : value || null;
		this.internals?.setFormValue(formValue);
	}

	@Watch("disabled")
	handleDisabledChange() {
		if (this.input) {
			// Disabled form controls are always valid, so we need to recheck validity when the state changes
			this.input.disabled = this.disabled;
			this.invalid = !this.input.checkValidity();
		}
	}

	/** Emitted when the control's value changes. */
	@Event({ eventName: "hbr-change" }) hbrChange: EventEmitter;

	/** Emitted when the clear button is activated. */
	@Event({ eventName: "hbr-clear" }) hbrClear: EventEmitter;

	/** Emitted when the control receives input. */
	@Event({ eventName: "hbr-input" }) hbrInput: EventEmitter;

	/** Emitted when the control gains focus. */
	@Event({ eventName: "hbr-focus" }) hbrFocus: EventEmitter;

	/** Emitted when the control loses focus. */
	@Event({ eventName: "hbr-blur" }) hbrBlur: EventEmitter;

	connectedCallback() {
		this.internals ??= attachElementInternals(this.host);
		this.handleFocusInput = this.handleFocusInput.bind(this);
		this.handleChange = this.handleChange.bind(this);
		this.handleInput = this.handleInput.bind(this);
		this.handleInvalid = this.handleInvalid.bind(this);
		this.handleBlur = this.handleBlur.bind(this);
		this.handleFocus = this.handleFocus.bind(this);
		this.handleClearClick = this.handleClearClick.bind(this);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.handleDisabledChange = this.handleDisabledChange.bind(this);
		this.handleInputWidth = this.handleInputWidth.bind(this);

		this.host.shadowRoot.addEventListener("slotchange", this.handleSlotChange);
	}
	componentWillLoad() {
		this.handleSlotChange();
		//Replacing with :has pseudo class. If native input is invalid, red border will be set.
		//this.invalid = !this.input?.checkValidity();
		this.handleInputWidth();
	}

	componentWillRender() {
		this.handleInputWidth();
	}

	disconnectedCallback() {
		this.host.shadowRoot.removeEventListener(
			"slotchange",
			this.handleSlotChange,
		);
	}

	/** Sets focus on the input. */
	@Method()
	async setFocus(options?: FocusOptions) {
		this.input.focus(options);
	}

	/** Removes focus from the input. */
	@Method()
	async removeFocus() {
		this.input.blur();
	}

	/** Selects all the text in the input. */
	@Method()
	async select() {
		return this.input.select();
	}

	/** Sets the start and end positions of the text selection (0-based). */
	@Method()
	async setSelectionRange(
		selectionStart: number,
		selectionEnd: number,
		selectionDirection: "forward" | "backward" | "none" = "none",
	) {
		return this.input.setSelectionRange(
			selectionStart,
			selectionEnd,
			selectionDirection,
		);
	}

	getValue = () => {
		return this.searchable ? this.inputValue : this.value;
	};

	setValue = (value) => {
		if (this.searchable) {
			this.inputValue = value;
		} else {
			this.value = value;
		}
	};

	/** Replaces a range of text with a new string. */
	@Method()
	async setRangeText(
		replacement: string,
		start: number,
		end: number,
		selectMode: "select" | "start" | "end" | "preserve" = "preserve",
	) {
		this.input.setRangeText(replacement, start, end, selectMode);

		if (this.getValue() !== this.input.value) {
			this.setValue(this.input.value);
			this.hbrChange.emit();
			this.hbrInput.emit();
		}
	}

	/** Checks for validity and shows the browser's validation message if the control is invalid. */
	@Method()
	async reportValidity() {
		return this.input.reportValidity();
	}

	/** Sets a custom validation message. If `message` is not empty, the field will be considered invalid. */
	@Method()
	async setCustomValidity(message: string) {
		this.input.setCustomValidity(message);
		this.invalid = !this.input.checkValidity();
	}

	handleInputWidth() {
		if (this.dynamicInputWidth) {
			if (this.getValue().length > 10 || this.placeholder) {
				this.host.style.setProperty("--input-width", "100%");
			} else {
				this.host.style.setProperty(
					"--input-width",
					`${this.getValue().length + 1}ch`,
				);
			}
		}
	}
	handleChange() {
		this.setValue(this.input.value);
		this.handleInputWidth();
		this.hbrChange.emit();
	}

	handleInput() {
		this.setValue(this.input.value);
		this.handleInputWidth();
		if (this.required) this.requiredAfterFocus = true;
		this.hbrInput.emit();
	}

	handleInvalid() {
		this.invalid = true;
	}

	handleBlur() {
		this.hasFocus = false;
		this.host.setAttribute("data-focused", "false");
		this.hbrBlur.emit();
	}

	handleFocus() {
		this.hasFocus = true;
		this.host.setAttribute("data-focused", "true");
		this.hbrFocus.emit();
	}

	handleClearClick(event: MouseEvent) {
		this.setValue("");
		this.handleInputWidth();
		this.hbrClear.emit();
		this.hbrInput.emit();
		this.hbrChange.emit();
		this.input.focus();

		event.stopPropagation();
	}

	handleFocusInput(event) {
		if (this.disabled || this.readonly) return;
		if (
			event.target.classList.contains("combobox__suffix-container") ||
			event.target.classList.contains("combobox") ||
			event.target.classList.contains("combobox__main")
		) {
			this.input?.focus();
		}
	}

	handleSlotChange() {
		this.hasHelpTextSlot = hasSlot(this.host, "help-text");
		this.hasLabelSlot = hasSlot(this.host, "label");
		this.hasLabelInfoSlot = hasSlot(this.host, "label-info");
		this.hasFrontSlot = hasSlot(this.host, "front");
		this.hasRearSlot = hasSlot(this.host, "rear");
		this.hasPrefixSlot = hasSlot(this.host, "prefix");
		this.hasSuffixSlot = hasSlot(this.host, "suffix");
		this.hasElementSuffix = hasSlot(this.host, "element-suffix");
	}
	handlePlaceholder = () => {
		if (this.dynamicPlaceholder && !this.multiple) {
			return this.hasFocus ? this.value || this.placeholder : this.placeholder;
		}
		return this.placeholder;
	};
	handleValue = () => {
		if (this.dynamicPlaceholder) {
			if (this.getValue() && this.open && !this.hasFocus)
				return this.getValue();
			return !this.hasFocus ? this.value : this.getValue();
		}
		return this.getValue();
	};
	handleIsEmpty = () => {
		if (this.dynamicPlaceholder) {
			return !(!this.hasFocus && this.value);
		}
		const value = this.getValue();
		if (Array.isArray(value)) return value.length === 0;
		return [null, undefined, ""].includes(value);
	};
	render() {
		const describedHelpId = this.hasHelpTextSlot ? this.helpTextId : "";
		const tooltipId = this.tooltip ? `${this.inputId}-tooltip` : "";
		const describedId =
			describedHelpId || tooltipId
				? `${describedHelpId} ${tooltipId}`
				: undefined;

		const optionalProps = {
			//due to the biome error on input autofocus
			autoFocus: this.autofocus,
		};

		const placeholder = this.handlePlaceholder() as string;
		const value = this.handleValue();
		const isEmpty = this.handleIsEmpty();
		const baseProps: BaseProps = {};
		if (this.multiple) {
			baseProps.onClick = this.handleFocusInput;
		}
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<Host aria-controls={this.aria?.controls || this.ariacontrols}>
				<FormControl
					inputId={this.inputId}
					label={this.label}
					labelId={this.labelId}
					hasLabelSlot={this.hasLabelSlot}
					hasLabelInfoSlot={this.hasLabelInfoSlot}
					hasFrontSlot={this.hasFrontSlot}
					hasRearSlot={this.hasRearSlot}
					helpTextId={this.helpTextId}
					hasHelpTextSlot={this.hasHelpTextSlot}
					hasElementSuffix={this.hasElementSuffix}
					size={this.size}
					source={"input"}
					hasFocus={this.hasFocus}
					hasValue={this.getValue()?.length > 0}
					hasError={this.error}
					isDisabled={this.disabled}
					isRequired={this.required}
					tooltip={this.tooltip}
					tooltipId={this.tooltip ? `${this.inputId}-tooltip` : undefined}
				>
					<div
						part={`base ${this.error ? " error" : ""}`}
						class={{
							combobox: true,

							// Sizes
							"combobox--small": this.size === "small",
							"combobox--medium": this.size === "medium",
							"combobox--large": this.size === "large",

							// States
							"combobox--disabled": this.disabled,
							"combobox--focused": this.hasFocus,
							"combobox--empty": isEmpty,
							"combobox--invalid": this.invalid,
							"combobox--error": this.error,
							"combobox--readonly": this.readonly,
						}}
						{...baseProps}
					>
						{this.hasPrefixSlot && (
							<span part="prefix" class="combobox__prefix" id={this.prefixId}>
								<slot name="prefix" />
							</span>
						)}

						<span part="main" class="combobox__main">
							<slot name="tags" />
							<input
								part="input"
								ref={(el) => {
									this.input = el;
								}}
								id={this.inputId}
								class={{
									combobox__control: true,
									combobox__number: this.type === "number",
									"combobox__no-input": !this.searchable,
								}}
								type={this.type}
								name={this.name}
								placeholder={placeholder}
								disabled={this.disabled}
								readonly={!this.searchable || this.readonly}
								minLength={this.minlength}
								maxLength={this.maxlength}
								min={this.min}
								max={this.max}
								step={this.step}
								value={value}
								autoCapitalize={this.autocapitalize}
								autoComplete={this.autocomplete}
								autoCorrect={this.autocorrect}
								{...optionalProps}
								spellcheck={this.spellcheck}
								pattern={this.pattern}
								required={this.requiredAfterFocus}
								inputMode={this.inputmode}
								onChange={this.handleChange}
								onInput={this.handleInput}
								onInvalid={this.handleInvalid}
								onFocus={this.handleFocus}
								onBlur={this.handleBlur}
								aria-expanded={this.open ? "true" : "false"}
								aria-haspopup={this.aria?.haspopup || this.ariahaspopup}
								aria-disabled={this.disabled ? "true" : "false"}
								aria-describedby={describedId}
								role={this.aria?.role || this.ariarole}
								aria-label={this.aria?.label || this.arialabel}
								aria-invalid={this.invalid ? "true" : "false"}
							/>
						</span>

						<span class="combobox__suffix-container">
							{this.clearable && (
								<button
									part="clear-button"
									class="combobox__clear"
									type="button"
									aria-label={
										this.aria?.deleteInputContent || "delete input content"
									}
									data-testid="clear-button"
									onClick={this.handleClearClick}
								>
									<slot name="clear-icon">
										<hbr-icon
											asset={customSystemIcons?.["x-circle"] || xCircle}
										/>
									</slot>
								</button>
							)}
							{this.invalid && (
								<hbr-visually-hidden>
									<div class="hidden" aria-live="polite" aria-atomic="true">
										Invalid Input
									</div>
								</hbr-visually-hidden>
							)}
							{this.hasSuffixSlot && (
								<span part="suffix" class="combobox__suffix" id={this.suffixId}>
									<slot name="suffix" />
								</span>
							)}
							{this.expandIcon && (
								<span part="expand-icon" class="combobox__expand-icon">
									<slot name="expand-icon">
										<hbr-icon
											class={{
												"combobox__expand-icon-caret": true,
												"combobox__expand-icon-caret-open": true,
											}}
											asset={customSystemIcons?.caret || caret}
										/>
									</slot>
								</span>
							)}
						</span>
					</div>
				</FormControl>
			</Host>
		);
	}
}
